function onSheetClick(e) {
  const d = e.currentTarget;
  const r = e.target.closest('.seg button[data-v]');
  if (r) { const k = r.parentElement.dataset.key; S[k] = r.dataset.v; saveSettings(); $$('button', r.parentElement).forEach(b => b.setAttribute('aria-checked', b === r)); return; }
  const s = e.target.closest('.switch');
  if (s) { const on = s.getAttribute('aria-checked') !== 'true'; S[s.dataset.key] = on; saveSettings(); s.setAttribute('aria-checked', on); return; }
  const b = e.target.closest('[data-act]'); if (!b) return;
  switch (b.dataset.act) {
    case 'export': exportData(); break;
    case 'report': copyReport(); break;
    case 'clear-hist': if (confirm('Forget which games you have played here?')) { store.del('ca_plays'); d.close(); location.reload(); } break;
    case 'clear-favs': if (confirm('Remove all favourites?')) { store.del('ca_favs'); d.close(); location.reload(); } break;
    case 'reset': Object.assign(S, DEF); saveSettings(); d.close(); openPrefs(); toast('Settings reset'); break;
    case 'install': if (installEvt) { installEvt.prompt(); installEvt = null; b.hidden = true; } break;
  }
}

