/* ---------- play page ---------- */
function play() {
  const player = $('#player'); if (!player) return;
  const id = new URLSearchParams(location.search).get('g');
  if (id === 'random') { location.replace(playHref(randomGame())); return; }
  const g = byId[id];
  if (!g) { location.replace('./'); return; }
  const c = catOf(g.cat);
  document.title = g.title + " — play free at Caleb's Arcade";
  $('meta[name=description]').content = g.blurb;
  markNav({ cat: g.cat });
  $('#crumb-cat').textContent = c.name; $('#crumb-cat').href = './?cat=' + c.id; $('#crumb-t').textContent = g.title;
  $('#backdrop').style.backgroundImage = 'url("' + g.thumb + '")';
  const shot = $('#shot'); shot.src = g.thumb2x || g.thumb; shot.alt = g.title;
  $('#title').textContent = g.title;
  const mic = (g.tags || []).includes('mic');
  $('#meta').innerHTML = '<span>' + esc(c.name) + '</span>' + (g.stage === 'tall' ? '<span>Portrait</span>' : '') + (mic ? '<span>Uses the mic</span>' : '') + (g.new ? '<span>New</span>' : '') + (g.pop && g.pop <= 10 ? '<span>Popular</span>' : '');
  $('#gi').src = g.thumb; $('#gtitle').textContent = g.title;
  $('#gcat').textContent = c.name; $('#gcat').href = './?cat=' + c.id;
  $('#gfrom').textContent = '· ' + fromLabel(g);
  $('#blurb').textContent = g.blurb;
  if (g.note) {
    $('#howwrap').hidden = false;
    $('#how').innerHTML = esc(g.note).replace(/\b(WASD|Space|Enter|Esc|Shift|Tab|[A-HJ-Z])\b(?![a-z'’])/g, '<kbd>$1</kbd>').replace(/\b(arrows|arrow keys)\b/g, '<kbd>←</kbd><kbd>→</kbd> $1');
  }
  $('#ext').hidden = !g.ext;
  $('#tags').innerHTML = [c.name, ...g.tags].map((t, i) => '<a href="' + (i === 0 ? './?cat=' + c.id : './?q=' + encodeURIComponent(t)) + '">' + (i === 0 ? '' : '#') + esc(t) + '</a>').join('');
  const facts = () => {
    const best = bestOf(g), p = plays()[g.id];
    const rows = [['Category', '<a href="./?cat=' + c.id + '">' + esc(c.name) + '</a>'], ['From', esc(fromLabel(g))], ['Screen', g.stage === 'tall' ? 'Portrait' : 'Landscape'], ['Players', g.players > 1 ? g.players + ' players' : '1 player'], ['Runs in', 'Your browser, no install']];
    if (g.mb) rows.push(['Download', (g.mb < 1 ? 'under 1 MB' : Math.round(g.mb) + ' MB') + (/Godot web build/.test(g.note) ? ' + 38 MB engine, once' : '')]);
    if (mic) rows.push(['Microphone', 'Optional, the browser asks first']);
    if (best != null) rows.push(['Your ' + esc(g.label || 'best'), '<b>' + best + '</b>']);
    if (p && p.n) rows.push(['You played', p.n + (p.n === 1 ? ' time' : ' times')]);
    $('#facts').innerHTML = rows.map(([k, v]) => '<div><dt>' + k + '</dt><dd>' + v + '</dd></div>').join('');
  };
  facts();

  const frame = $('#frame'), splash = $('#splash'), load = $('#load'), fs = $('#fs');
  let started = false;
  function start() {
    if (started) return; started = true;
    splash.classList.add('gone'); load.classList.remove('off'); $('#loadtxt').textContent = 'Loading ' + g.title + '…';
    // A game tagged 'mic' also gets microphone access; the browser still asks the player.
    if (mic) frame.allow = frame.allow + '; microphone';
    frame.hidden = false; frame.title = g.title; frame.src = g.src;
    const done = () => { load.classList.add('off'); try { frame.focus(); } catch (e) {} };
    frame.addEventListener('load', done, { once: true }); setTimeout(() => load.classList.add('off'), 9000);
    recordPlay(g.id); facts();
  }
  // phones: Play goes straight to fullscreen (theatre where the browser has no fullscreen API)
  const phonePlay = () => { start(); if (touch.matches && innerWidth <= 760) fs.click(); };
  $('#playbtn').addEventListener('click', phonePlay);
  splash.addEventListener('click', e => { if (!e.target.closest('a,button')) phonePlay(); });
  const alt = $('#alt');
  alt.innerHTML = '<a href="' + esc(g.src) + '" target="_blank" rel="noopener">' + ico('ext') + ' Open in a new tab</a>';
  $('a', alt).addEventListener('click', () => recordPlay(g.id));
  if (g.ext && S.extnew) { $('#playbtn').lastChild.textContent = 'Play here'; $('a', alt).style.cssText = 'opacity:1;background:rgba(255,255,255,.22)'; }
  const snote = $('#snote');
  if (/Godot web build/.test(g.note)) { snote.hidden = false; snote.textContent = 'Godot game: ' + (g.mb >= 1 ? Math.round(g.mb) + ' MB to download, plus ' : '') + 'the shared 38 MB engine the first time. Desktop browsers are happiest.'; }
  else if (/Unity WebGL/.test(g.note)) { snote.hidden = false; snote.textContent = 'About 16 MB to load the first time. Happiest in a desktop browser.'; }
  else if (mic) { snote.hidden = false; snote.textContent = 'Some rounds use your microphone. The browser asks first; everything else works without it.'; }
  $('#open').href = g.src;

  // screen size: per-game memory > the visitor's default > the game's own preferred shape
  const modes = store.get('ca_stage', {});
  const startMode = modes[g.id] || (S.stage !== DEF.stage ? S.stage : (g.stage || S.stage));
  const setMode = m => { player.dataset.mode = m; };
  setMode(startMode);
  // popovers (share + size)
  let openPop = null;
  const closePop = () => { if (openPop) { openPop.pop.remove(); openPop.btn.setAttribute('aria-expanded', 'false'); openPop = null; } };
  function pop(btn, html, bind) {
    if (openPop && openPop.btn === btn) { closePop(); return; } closePop();
    const p = document.createElement('div'); p.className = 'pop'; p.innerHTML = html; btn.parentElement.appendChild(p); btn.setAttribute('aria-expanded', 'true');
    openPop = { pop: p, btn }; bind(p); const f = $('button,a', p); if (f) f.focus();
  }
  document.addEventListener('click', e => { if (openPop && !e.target.closest('.menu-pop')) closePop(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && openPop) { const b = openPop.btn; closePop(); b.focus(); } });
  $('#sizeb').addEventListener('click', () => pop($('#sizeb'), '<h3>Screen size</h3>' + OPTS.stage.map(([v, n]) => '<button type="button" role="menuitemradio" data-v="' + v + '" aria-checked="' + (player.dataset.mode === v) + '">' + n + '</button>').join(''), p => p.addEventListener('click', e => {
    const b = e.target.closest('button[data-v]'); if (!b) return; setMode(b.dataset.v); const m = store.get('ca_stage', {}); m[g.id] = b.dataset.v; store.set('ca_stage', m); closePop(); toast('Screen: ' + b.textContent);
  })));
  const url = location.origin + location.pathname + '?g=' + encodeURIComponent(g.id);
  const shareText = 'Play ' + g.title + ' free at Caleb\'s Arcade';
  $('#share').addEventListener('click', () => pop($('#share'), '<h3>Share this game</h3><button type="button" data-s="copy">' + ico('link') + 'Copy link</button>' + (navigator.share ? '<button type="button" data-s="native">' + ico('share') + 'Share…</button>' : '') +
    '<a href="https://wa.me/?text=' + encodeURIComponent(shareText + ' ' + url) + '" target="_blank" rel="noopener">' + ico('chat') + 'WhatsApp</a>' +
    '<a href="https://twitter.com/intent/tweet?text=' + encodeURIComponent(shareText) + '&url=' + encodeURIComponent(url) + '" target="_blank" rel="noopener">' + ico('ext') + 'Post on X</a>' +
    '<a href="mailto:?subject=' + encodeURIComponent(shareText) + '&body=' + encodeURIComponent(url) + '">' + ico('mail') + 'Email</a>', p => p.addEventListener('click', async e => {
    const b = e.target.closest('[data-s]'); if (!b) { if (e.target.closest('a')) closePop(); return; }
    if (b.dataset.s === 'copy') { try { await navigator.clipboard.writeText(url); toast('Link copied'); } catch (err) { prompt('Copy this link', url); } closePop(); }
    else { closePop(); try { await navigator.share({ title: g.title + " — Caleb's Arcade", text: g.blurb, url }); } catch (err) {} }
  })));
  // fullscreen, with a theatre-mode fallback for browsers without the fullscreen API (iPhone Safari)
  const canFs = !!(player.requestFullscreen || player.webkitRequestFullscreen);
  const theatre = on => { document.body.classList.toggle('theatre', on); if (!on) player.scrollIntoView(scrollOpts({ block: 'center' })); };
  fs.addEventListener('click', () => {
    start();
    if (document.fullscreenElement || document.webkitFullscreenElement) { (document.exitFullscreen || document.webkitExitFullscreen).call(document); return; }
    if (document.body.classList.contains('theatre')) { theatre(false); return; }
    if (canFs) { const r = (player.requestFullscreen || player.webkitRequestFullscreen).call(player); if (r && r.catch) r.catch(() => theatre(true)); } else theatre(true);
  });
  $('#exit').addEventListener('click', () => theatre(false));
  if (!canFs) { $('.lbl', fs).textContent = 'Theatre'; fs.setAttribute('aria-label', 'Theatre mode'); }
  // like / dislike / favourite
  const likeB = $('#like'), disB = $('#dislike'), favb = $('#favb');
  const paintLike = () => { const v = likes()[g.id] || 0; likeB.classList.toggle('on', v > 0); likeB.setAttribute('aria-pressed', v > 0); disB.classList.toggle('on', v < 0); disB.setAttribute('aria-pressed', v < 0); $('.lbl', likeB).textContent = v > 0 ? 'Liked' : 'Like'; };
  const setLike = v => { const l = likes(); if (l[g.id] === v) delete l[g.id]; else l[g.id] = v; store.set('ca_likes', l); paintLike(); if (l[g.id]) toast(v > 0 ? 'Glad you like it!' : 'Thanks, noted. Tester feedback below tells Caleb why.'); };
  likeB.addEventListener('click', () => setLike(1)); disB.addEventListener('click', () => setLike(-1)); paintLike();
  const paintFav = () => { const on = isFav(g.id); favb.classList.toggle('on', on); favb.setAttribute('aria-pressed', on); $('.lbl', favb).textContent = on ? 'Favourited' : 'Favourite'; };
  favb.addEventListener('click', () => { const on = toggleFav(g.id); toast(on ? 'Added to your favourites' : 'Removed from your favourites'); }); paintFav();
  document.addEventListener('favchange', paintFav);
  const restart = () => { if (!started) { start(); return; } load.classList.remove('off'); frame.src = 'about:blank'; setTimeout(() => { frame.src = g.src; frame.addEventListener('load', () => load.classList.add('off'), { once: true }); }, 40); };
  $('#reload').addEventListener('click', restart);
  // tester feedback
  const rate = $('#rate'), note = $('#note'), saved = $('#notesaved');
  const paintRate = () => { const r = (notes()[g.id] || {}).r; $$('button', rate).forEach(b => b.setAttribute('aria-checked', b.dataset.v === r)); };
  note.value = (notes()[g.id] || {}).note || ''; paintRate();
  if (notes()[g.id]) $('#fb').open = true;
  rate.addEventListener('click', e => { const b = e.target.closest('button[data-v]'); if (!b) return; const cur = (notes()[g.id] || {}).r; setNote(g.id, { r: cur === b.dataset.v ? '' : b.dataset.v }); paintRate(); saved.textContent = cur === b.dataset.v ? '' : 'Saved: ' + RATE[b.dataset.v] + '.'; });
  let noteT; note.addEventListener('input', () => { clearTimeout(noteT); noteT = setTimeout(() => { setNote(g.id, { note: note.value.trim() }); saved.textContent = note.value.trim() ? 'Note saved.' : ''; }, 400); });
  // up next + more rows
  const rel = related(g, 11), side = $('#related');
  rel.forEach((x, i) => side.appendChild(tile(x, { eager: i < 3 })));
  const more = $('#more');
  const sameCat = sortList(CATALOG.filter(x => x.cat === g.cat && x.id !== g.id && !rel.includes(x)), 'featured');
  const r1 = rowSection('More ' + c.name + ' games', sameCat.slice(0, 16), { icon: c.icon, cc: 'var(--c-' + c.id + ')', more: './?cat=' + c.id, moreLabel: 'All ' + (sameCat.length + 1) }); if (r1) more.appendChild(r1);
  more.appendChild(rowSection('Popular', popular().filter(x => x.id !== g.id).slice(0, 16), { icon: 'flame', cc: 'var(--c-hyper)', more: './?view=popular', ranked: true }));
  // play-page search: suggestions under the box
  suggest();
  document.addEventListener('keydown', e => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const tag = (e.target.tagName || '').toLowerCase(); if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
    if ($('dialog[open]')) return;
    const k = e.key.toLowerCase();
    if (k === 'f') { e.preventDefault(); fs.click(); }
    else if (k === 'r') { e.preventDefault(); restart(); }
    else if (k === 'n' && rel[0]) { e.preventDefault(); location.href = playHref(rel[0]); }
    else if (k === 'l') { e.preventDefault(); setLike(1); }
    else if (k === 'p' && !started) { e.preventDefault(); start(); }
    else if (e.key === 'Escape' && document.body.classList.contains('theatre')) theatre(false);
  });
}
function suggest() {
  const q = $('#q'), box = $('#sugg'); if (!box) return;
  let sel = -1, items = [];
  const close = () => { box.hidden = true; q.setAttribute('aria-expanded', 'false'); q.removeAttribute('aria-activedescendant'); sel = -1; };
  const paint = () => $$('a', box).forEach((a, i) => { a.setAttribute('aria-selected', i === sel); if (i === sel) { q.setAttribute('aria-activedescendant', a.id); a.scrollIntoView({ block: 'nearest' }); } });
  q.addEventListener('input', () => {
    const v = q.value.trim(); if (!v) { close(); return; }
    const res = searchGames(v); items = res.slice(0, 7);
    box.innerHTML = items.length ? items.map((g, i) => '<a id="sg-' + i + '" role="option" href="' + playHref(g) + '"><img src="' + g.thumb + '" alt="" width="64" height="40"><span>' + esc(g.title) + '<small>' + esc(catName(g.cat)) + '</small></span></a>').join('') +
      '<a class="all" id="sg-' + items.length + '" role="option" href="./?q=' + encodeURIComponent(v) + '">See all ' + res.length + ' results</a>' : '<p>No games match “' + esc(v) + '”.</p>';
    box.hidden = false; q.setAttribute('aria-expanded', 'true'); sel = -1; paint();
  });
  q.addEventListener('keydown', e => {
    const links = $$('a', box);
    if (e.key === 'ArrowDown' && !box.hidden) { e.preventDefault(); sel = Math.min(links.length - 1, sel + 1); paint(); }
    else if (e.key === 'ArrowUp' && !box.hidden) { e.preventDefault(); sel = Math.max(-1, sel - 1); paint(); }
    else if (e.key === 'Enter') { e.preventDefault(); const v = q.value.trim(); if (sel >= 0 && links[sel]) location.href = links[sel].href; else if (v) location.href = './?q=' + encodeURIComponent(v); }
    else if (e.key === 'Escape') { q.value = ''; close(); q.blur(); document.body.classList.remove('searching'); }
  });
  q.addEventListener('blur', () => setTimeout(close, 180));
}

